L21_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "그래? 그거 아쉽게 됐군."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "そうなのか？　それは残念だ。"
L21_1.m_Talk_ENG = "Really? That's a shame."
L21_1.m_Talk_TWN = "真的嗎？那真可惜。"
L21_1.m_Talk_SCN = "是吗？真是可惜。"
L21_1.m_Talk_DEU = "Really? That's a shame."
L21_1.m_Talk_FRA = "Really? That's a shame."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE1_START@16#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 612
L22_1.m_CutScenStrID = "EP13_ACT4_STAGE1_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "하지만 그래도 지금까지 소중하게 간직해 주어서 무척 기쁘다네."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "だが、それでも今まで大事にしてくれてとても嬉しい。"
L22_1.m_Talk_ENG = "Still, I'm truly grateful you've treasured it until now."
L22_1.m_Talk_TWN = "不過，我真的很感激你一直珍惜著它。"
L22_1.m_Talk_SCN = "不过，直到现在你一直珍藏着它，我感到非常高兴。"
L22_1.m_Talk_DEU = "Still, I'm truly grateful you've treasured it until now."
L22_1.m_Talk_FRA = "Still, I'm truly grateful you've treasured it until now."
