L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE1_START@18#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 612
L25_1.m_CutScenStrID = "EP13_ACT4_STAGE1_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_PRIDE"
L25_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "후후, 그건 그렇고 어느새 키가 훌쩍 자라버렸군."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "ふふ、それはそうとして、いつの間にか背が伸びたんたな。"
L25_1.m_Talk_ENG = "Haha, and look at you now. You've grown so tall."
L25_1.m_Talk_TWN = "哈哈，看看你現在，長得真高了。"
L25_1.m_Talk_SCN = "哟哟哟，说起来，你什么时候长这么高了？"
L25_1.m_Talk_DEU = "Haha, and look at you now. You've grown so tall."
L25_1.m_Talk_FRA = "Haha, and look at you now. You've grown so tall."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE1_START@19#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 612
L26_1.m_CutScenStrID = "EP13_ACT4_STAGE1_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "이제는 정말로 훌륭한 레이디라고 불러도 손색이 없겠어."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "もう立派なレディーと呼んでもいいくらいだ。"
L26_1.m_Talk_ENG = "You've become a proper lady, without a doubt."
L26_1.m_Talk_TWN = "你絕對是一位真正的淑女了。"
L26_1.m_Talk_SCN = "现在称你为真正出色的女士也不为过了。"
L26_1.m_Talk_DEU = "You've become a proper lady, without a doubt."
L26_1.m_Talk_FRA = "You've become a proper lady, without a doubt."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP13_ACT4_STAGE1_START@20#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 612
L27_1.m_CutScenStrID = "EP13_ACT4_STAGE1_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_LAUGH"
L27_1.m_CharStrID = "SWAN_SIX_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "그러는 당신은 여전히 제 기억 속 그 모습 그대로군요."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "そういうあなたは、相変わらず私の記憶の中のままですね。"
L27_1.m_Talk_ENG = "And yet you look exactly the same as you do in my memory."
L27_1.m_Talk_TWN = "但你看起來和我記憶中的一模一樣。"
L27_1.m_Talk_SCN = "而你依然是我记忆中的那个样子。"
L27_1.m_Talk_DEU = "And yet you look exactly the same as you do in my memory."
L27_1.m_Talk_FRA = "And yet you look exactly the same as you do in my memory."
