L36_1.m_Pos = "R"
L36_1.m_Talk_KOREA = "그리고 자네가 정말로 모든 걸 돌이킬 수 있는 힘을 얻게 되었다면……."
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "そして君が本当に全てを元に戻せる力を手に入れたのなら……"
