L47_1 = "분명 내가 가늠하는 것보다도 훨씬 정확하고 방대한 양의 정보를 기억하겠지."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "きっと私が推測しているよりもずっと、正確で膨大な量の情報を記憶しているのだろう。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You probably remember far more than I could ever imagine."
L46_1.m_Talk_ENG = L47_1
L47_1 = "肯定比我估計的要記住更準確和龐大的資訊量。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "肯定比我估计的要记住更准确和庞大的信息量。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "You probably remember far more than I could ever imagine."
L46_1.m_Talk_DEU = L47_1
L47_1 = "You probably remember far more than I could ever imagine."
