L48_1 = "하지만 자네라도 모든 걸 알지는 못해. 자네가 경험하지 못한 건 기억할 수 없지."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "だが、君であっても全てを知ることはできない。君が経験できなかったことは記憶できないからな。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "But even you don't know everything. You can't remember what you've never experienced."
L47_1.m_Talk_ENG = L48_1
L48_1 = "但是即使是你也不可能知道一切。你沒有經歷過的事情是無法記住的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "但是即使是你也不可能知道一切。你没有经历过的事情是无法记住的。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "But even you don't know everything. You can't remember what you've never experienced."
L47_1.m_Talk_DEU = L48_1
L48_1 = "But even you don't know everything. You can't remember what you've never experienced."
L47_1.m_Talk_FRA = L48_1
