L49_1 = "그리고 이 세계에서 자네의 기억 밖에 있는 것은 존재할 수 없어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そして、この世界で君の記憶にないものは存在できない。"
