L41_1 = "비록 도시 하나뿐인 세계에 불과하더라도 이 세계는 제가 구상한 각본이랍니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "たとえ都市一つ限りの世界だとしても、この世界は私が構想した脚本です。"
