L49_1 = "줄곧, 내가 자네에게 진실을 전하는 걸 망설였기 때문일 테니까."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ずっと、私が君に真実を伝えることをためらっていたせいだから。"
