L50_1 = "그러니까 이번만큼은 자네를 외면하지 않고 똑바로 자네와 마주해야겠지."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "だから今回だけはきちんと、君と向き合うべきだろう。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "So this time, I won't turn away. I'll face you head-on."
L49_1.m_Talk_ENG = L50_1
L50_1 = "所以這一次，我不會逃避。我要正面迎戰你。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "所以这次我不会再回避你，而是要正视你。"
