L17_1.m_Pos = "C"
L18_1 = "잘못된 선택을 했다면, 고쳐 나가면 돼. 죄를 저질렀다면 그만큼 몇 번이고 속죄하게."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "間違った選択をしたなら、直していけばいい。罪を犯したのなら、その分、何度でも償いたまえ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "If you made a mistake, then correct it. If you sinned, then atone for it."
L17_1.m_Talk_ENG = L18_1
L18_1 = "如果你犯了錯，就去改正它。如果你有罪，就去贖罪。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "如果做出了错误的选择，那就去改正。如果犯了罪，不管多少次，都要赎罪。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "If you made a mistake, then correct it. If you sinned, then atone for it."
L17_1.m_Talk_DEU = L18_1
L18_1 = "If you made a mistake, then correct it. If you sinned, then atone for it."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP13_ACT4_STAGE1_START@87#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 612
