L18_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L18_1.m_Pos = "C"
L19_1 = "그걸 알려주기 위해서라도, 나는 이 자리에서 자네의 계획을 저지하겠어, 아이린."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "それを教えるためにも、私はこの場で君の計画を阻止する、アイリーン。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "To help you realize that, I'll stop your plan here, Irene."
L18_1.m_Talk_ENG = L19_1
L19_1 = "為了讓你明白這一點，我會在這裡阻止你的計畫，愛琳。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "为了告诉你这一点，我会在这里阻止你的计划，艾琳。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "To help you realize that, I'll stop your plan here, Irene."
L18_1.m_Talk_DEU = L19_1
L19_1 = "To help you realize that, I'll stop your plan here, Irene."
L18_1.m_Talk_FRA = L19_1
