L7_1 = "<color=#ffd34c>세계를 만드는 법칙</color>에서 떨어져 나온 일부라고 할 수 있답니다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "<color=#ffd34c>世界を作る法則</color>から抜け落ちた一部だと言えるのです。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "She's a fragment torn from <color=#ffd34c>the law of creating a world</color>."
L6_1.m_Talk_ENG = L7_1
L7_1 = "可以說是從<color=#ffd34c>創造世界的法則</color>中脫離出來的一部分。"
L6_1.m_Talk_TWN = L7_1
